-- HOSTED tenant foundation for the TaxiFlow pilot (release candidate; NOT APPLIED).
-- GENERATED by scripts/localdb/hosted-copy/build-hosted-foundation.mjs; edit the
-- local foundation or hosted-access.sql, then rebuild.
-- Written against the read-only live inventory of 2026-10-10
-- (project-os/05-build/hosted-inventory.md). Apply only with Tebogo's approval,
-- after the encrypted backup, in its own transaction, as the project owner.
-- Rehearsed locally on an exact synthetic copy of the live schema:
--   node scripts/localdb/setup.mjs hosted && node scripts/localdb/hosted-rehearsal-tests.mjs
--
-- Differences from the local foundation:
-- * drops EVERY policy on workspace_snapshots (the live names, found dynamically);
-- * revokes ALL anon/authenticated/PUBLIC privileges on EVERY public relation
--   (9 tables + the compliance_dashboard view; live grants include TRUNCATE),
--   enables RLS on the 8 unused legacy tables (no policies = no browser access)
--   and makes the view security_invoker;
-- * revokes the live default privileges that hand anon/authenticated access to
--   future tables, functions and sequences;
-- * never creates the browser membership RPC (set_business_membership);
-- * ends with assertions that abort (and roll back) if any browser access remains
--   or the existing workspace would have no active Owner.
-- The 8 legacy tables are empty on live and are kept (no data is dropped).

-- --- Preconditions -------------------------------------------------------------
do $$ begin
  if to_regclass('public.workspace_snapshots') is null then
    raise exception 'workspace_snapshots is missing; this is not the expected TaxiFlow database.';
  end if;
end $$;

-- === Core: copied unchanged from the local foundation (lines 5-125) ===
create schema if not exists taxiflow_private;
revoke all on schema taxiflow_private from public, anon, authenticated;

-- --- Tables -------------------------------------------------------------------

create table if not exists public.businesses (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{2,62}$'),
  name text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.business_memberships (
  business_id uuid not null references public.businesses (id) on delete restrict,
  user_id uuid not null references auth.users (id) on delete cascade,
  role text not null check (role in ('Owner', 'Admin', 'Manager', 'Driver')),
  driver_staff_id text,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id),
  primary key (business_id, user_id),
  constraint driver_needs_staff_id check (role <> 'Driver' or driver_staff_id is not null)
);

create unique index if not exists business_memberships_driver_staff_unique
  on public.business_memberships (business_id, driver_staff_id)
  where driver_staff_id is not null;

alter table public.workspace_snapshots add column if not exists business_id uuid;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'workspace_snapshots_business_fkey') then
    alter table public.workspace_snapshots
      add constraint workspace_snapshots_business_fkey foreign key (business_id) references public.businesses (id) on delete restrict;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'workspace_snapshots_business_unique') then
    alter table public.workspace_snapshots add constraint workspace_snapshots_business_unique unique (business_id);
  end if;
end $$;

-- --- Explicit mapping of the existing workspace (no shared fallback) ------------

insert into public.businesses (id, slug, name)
values ('10000000-0000-4000-8000-00000000000a', 'taxiflow-legacy', 'TaxiFlow Pro')
on conflict (id) do nothing;

update public.workspace_snapshots
set business_id = '10000000-0000-4000-8000-00000000000a'
where workspace_key = 'taxiflow-live' and business_id is null;

do $$ begin
  if exists (select 1 from public.workspace_snapshots where business_id is null) then
    raise exception 'Unmapped workspace_snapshots rows exist; add an explicit business mapping before applying the tenant foundation.';
  end if;
end $$;

alter table public.workspace_snapshots alter column business_id set not null;

-- Memberships only for exact, active, allowed-role appUsers matches. Unmatched
-- accounts get no access (fail closed). Viewer is never a membership.
insert into public.business_memberships (business_id, user_id, role, driver_staff_id, active)
select s.business_id, u.id, a ->> 'role', nullif(trim(a ->> 'staffId'), ''), true
from public.workspace_snapshots s
cross join lateral jsonb_array_elements(coalesce(s.snapshot -> 'appUsers', '[]'::jsonb)) a
join auth.users u on lower(u.email) = lower(trim(a ->> 'email'))
where s.workspace_key = 'taxiflow-live'
  and coalesce((a ->> 'active')::boolean, true)
  and a ->> 'role' in ('Owner', 'Admin', 'Manager', 'Driver')
  and (a ->> 'role' <> 'Driver' or nullif(trim(a ->> 'staffId'), '') is not null)
on conflict (business_id, user_id) do nothing;

-- --- Helpers (security definer, fixed search_path) -----------------------------

create or replace function taxiflow_private.is_active_member(p_business_id uuid, p_roles text[] default null)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.business_memberships m
    where m.business_id = p_business_id
      and m.user_id = auth.uid()
      and m.active
      and (p_roles is null or m.role = any (p_roles))
  );
$$;

create or replace function taxiflow_private.forbid_tenant_reassignment()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Separate branches: PL/pgSQL resolves every NEW field named in an
  -- expression, so a combined condition naming new.user_id breaks every
  -- workspace_snapshots update (that table has no user_id).
  if tg_table_name = 'workspace_snapshots' then
    if new.business_id is distinct from old.business_id then
      raise exception 'A workspace snapshot cannot be moved to another business.' using errcode = '42501';
    end if;
  elsif tg_table_name = 'business_memberships' then
    if new.business_id is distinct from old.business_id or new.user_id is distinct from old.user_id then
      raise exception 'A membership cannot be moved to another business or user.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists workspace_snapshots_no_tenant_reassignment on public.workspace_snapshots;
create trigger workspace_snapshots_no_tenant_reassignment
  before update on public.workspace_snapshots
  for each row execute function taxiflow_private.forbid_tenant_reassignment();

drop trigger if exists business_memberships_no_reassignment on public.business_memberships;
create trigger business_memberships_no_reassignment
  before update on public.business_memberships
  for each row execute function taxiflow_private.forbid_tenant_reassignment();

-- === Hosted access section (replaces the local grants/RLS section) =============

-- Every policy on workspace_snapshots (live: "Authenticated users can
-- read/insert/update workspace snapshots"), whatever it is called.
do $$
declare p record;
begin
  for p in select policyname from pg_policies where schemaname = 'public' and tablename = 'workspace_snapshots' loop
    execute format('drop policy %I on public.workspace_snapshots', p.policyname);
  end loop;
end $$;

-- Every privilege anon, authenticated and PUBLIC hold on any public relation
-- (tables, views, sequences), then RLS on every public table.
do $$
declare r record;
begin
  for r in
    select c.relname, c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'S', 'f')
  loop
    if r.relkind = 'S' then
      execute format('revoke all on sequence public.%I from anon, authenticated, public', r.relname);
    else
      execute format('revoke all on table public.%I from anon, authenticated, public', r.relname);
    end if;
    if r.relkind in ('r', 'p') then
      execute format('alter table public.%I enable row level security', r.relname);
    end if;
  end loop;
end $$;

-- The legacy view must not run with its owner's rights.
alter view if exists public.compliance_dashboard set (security_invoker = true);

-- Every public function: no execute for anon, authenticated or PUBLIC (live has
-- none today; this also covers anything added since the inventory).
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' loop
    execute format('revoke all on function %s from anon, authenticated, public', f.sig);
  end loop;
end $$;

-- Live default privileges hand anon/authenticated everything on new objects
-- created by postgres in public. Remove them. (TaxiFlow never creates objects
-- as supabase_admin; explicit revokes in every migration still apply.)
alter default privileges for role postgres in schema public revoke all on tables from anon, authenticated, public;
alter default privileges for role postgres in schema public revoke all on sequences from anon, authenticated, public;
alter default privileges for role postgres in schema public revoke all on functions from anon, authenticated, public;

-- The only browser access the tenant model needs: read your own memberships and
-- businesses (RLS limits the rows). Everything else goes through the server.
grant select on table public.businesses to authenticated;
grant select on table public.business_memberships to authenticated;

revoke all on function taxiflow_private.is_active_member(uuid, text[]) from public, anon, authenticated, service_role;
revoke all on function taxiflow_private.forbid_tenant_reassignment() from public, anon, authenticated;
grant usage on schema taxiflow_private to authenticated;
grant execute on function taxiflow_private.is_active_member(uuid, text[]) to authenticated;

drop policy if exists "members read their businesses" on public.businesses;
create policy "members read their businesses" on public.businesses
  for select to authenticated
  using (taxiflow_private.is_active_member(id));

drop policy if exists "read own or administered memberships" on public.business_memberships;
create policy "read own or administered memberships" on public.business_memberships
  for select to authenticated
  using (
    (user_id = auth.uid() and active)
    or taxiflow_private.is_active_member(business_id, array['Owner', 'Admin'])
  );

-- --- Assertions (any failure aborts and rolls back this migration) ----------------
do $$
declare
  leftover text;
begin
  select string_agg(policyname, ', ') into leftover
  from pg_policies where schemaname = 'public' and tablename = 'workspace_snapshots';
  if leftover is not null then raise exception 'Policies remain on workspace_snapshots: %', leftover; end if;

  select string_agg(table_name || ':' || grantee || ':' || privilege_type, ', ' order by table_name, grantee, privilege_type) into leftover
  from information_schema.role_table_grants
  where table_schema = 'public'
    and (grantee in ('anon', 'PUBLIC')
         or (grantee = 'authenticated' and not (table_name in ('businesses', 'business_memberships') and privilege_type = 'SELECT')));
  if leftover is not null then raise exception 'Browser grants remain: %', leftover; end if;

  select string_agg(c.relname, ', ') into leftover
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relrowsecurity;
  if leftover is not null then raise exception 'Tables without RLS: %', leftover; end if;

  select string_agg(p.oid::regprocedure::text, ', ') into leftover
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
  if leftover is not null then raise exception 'Browser-executable public functions: %', leftover; end if;

  if not exists (
    select 1 from public.business_memberships m
    where m.business_id = '10000000-0000-4000-8000-00000000000a' and m.role = 'Owner' and m.active
  ) then
    raise exception 'The existing workspace would have no active Owner; stop and add the operator Owner step first.';
  end if;
end $$;
